-- Migration 0014 — checkout idempotency + coupon usage-limit backstop.
-- APPLIED LIVE 2026-11-12 (SQL Editor, user-approved; 'Success. No rows returned').
-- Applied BEFORE deploying the 14-medium fix batch: until it was applied, guest DB checkout
-- would have failed on the orders.user_id NOT NULL below, and the idempotency
-- uniqueness was enforced only by the application lookup, not the database.
--
-- What it does (audit run-1, head 9c305966, mediums #1 and #3):
--
--   * orders.idempotency_key — one UUID per checkout attempt,
--     generated by the client (components/checkout/checkout-form.tsx)
--     and stored on the row. A repeat submission with the same key
--     returns the ORIGINAL order instead of a second order and a
--     second stock decrement (lib/orders/server/create.ts).
--   * UNIQUE(user_id, idempotency_key) — the database backstop, so
--     two concurrent duplicates cannot both insert. Postgres treats
--     NULLs as distinct in a UNIQUE constraint, so this alone does
--     NOT dedup guest orders (user_id NULL): the guest partial index
--     below covers that case, and guests are expressly included —
--     the server lookup uses IS NULL for them.
--   * orders.user_id DROP NOT NULL — the 0001 schema required a
--     user; guest orders are real rows with user_id NULL (and a
--     buyerToken held in the checkout's in-memory record). NULL
--     user_ids are invisible to the customer RLS policies (they
--     match auth.uid() = user_id), which is the safe default — a
--     guest order is reached by its buyerToken, not by a session.
--   * coupons CHECK (used_count <= usage_limit) — the backstop for
--     the atomic claim in lib/orders/checkout/coupons.ts: even if
--     two checkouts ever raced past the conditional update, the
--     database refuses to hold more redemptions than the limit.
--
-- Safe to run once: the column is added only if missing, existing
-- rows keep NULL keys (NULLs never collide in either unique index),
-- and the CHECK passes on any database whose counts are already
-- within their limits. No RLS changes. Idempotent re-runs are NOT
-- supported for the constraint/index names (plain statements, like
-- the earlier migrations) — run it once.

alter table public.orders
  add column if not exists idempotency_key text;

-- Guest orders need a NULL user_id (see above).
alter table public.orders
  alter column user_id drop not null;

-- Signed-in dedup: one order per (user, idempotency key).
alter table public.orders
  add constraint orders_idempotency_unique unique (user_id, idempotency_key);

-- Guest dedup: one order per idempotency key when user_id IS NULL
-- (the constraint above cannot see NULL user_ids as equal).
create unique index orders_idempotency_guest_idx
  on public.orders (idempotency_key)
  where user_id is null and idempotency_key is not null;

-- Coupon usage backstop: used_count can never exceed usage_limit.
alter table public.coupons
  add constraint coupons_used_count_within_limit
  check (usage_limit is null or used_count <= usage_limit);

comment on column public.orders.idempotency_key is
  'One UUID per checkout attempt, generated by the client. A repeat submission with the same key returns the original order instead of inserting a second one (migration 0014, audit run-1 medium #1).';
